import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const generatedTypeHeader =
  "// Generated by scripts/office-v2-contracts-generate.mjs. Do not edit.";

const repositoryRoot = resolve(import.meta.dirname, "..");
const schemaRelativePath = "docs/office-v2/schemas/common-v2.schema.json";
const generatedRelativePath = "packages/office-v2-contracts/src/generated/common-v2.ts";
const schemaId = "https://affiliate-operations.example/schemas/office-v2/common-v2.schema.json";

function typeNameFromDefinition(name) {
  return name
    .split(/[-_]/u)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("");
}

function literal(value) {
  return JSON.stringify(value);
}

function referenceName(reference) {
  const prefix = "#/$defs/";
  if (!reference.startsWith(prefix)) {
    throw new Error(`contract.generator-unsupported-schema: external reference ${reference}`);
  }
  return typeNameFromDefinition(reference.slice(prefix.length));
}

function propertyName(name) {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/u.test(name) ? name : literal(name);
}

function union(values) {
  return values.length === 1 ? values[0] : values.join(" | ");
}

function typeForSchema(schema) {
  if (schema.$ref) return referenceName(schema.$ref);
  if (Object.hasOwn(schema, "const")) return literal(schema.const);
  if (schema.enum) return union(schema.enum.map(literal));
  if (schema.oneOf) return union(schema.oneOf.map(typeForSchema));
  if (schema.anyOf) return union(schema.anyOf.map(typeForSchema));
  if (schema.allOf || schema.not || schema.if || schema.then || schema.else) {
    throw new Error("contract.generator-unsupported-schema: conditional or intersection keyword");
  }
  if (schema.type === "string") return "string";
  if (schema.type === "integer" || schema.type === "number") return "number";
  if (schema.type === "boolean") return "boolean";
  if (schema.type === "null") return "null";
  if (schema.type === "array") {
    if (!schema.items) throw new Error("contract.generator-unsupported-schema: array without items");
    return `ReadonlyArray<${typeForSchema(schema.items)}>`;
  }
  if (schema.type === "object") {
    if (schema.additionalProperties === true) {
      throw new Error("contract.generator-unsupported-schema: open object");
    }
    const required = new Set(schema.required ?? []);
    const properties = Object.entries(schema.properties ?? {})
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([name, property]) => (
        `  readonly ${propertyName(name)}${required.has(name) ? "" : "?"}: ${typeForSchema(property)};`
      ));
    return `{
${properties.join("\n")}
}`;
  }
  throw new Error(`contract.generator-unsupported-schema: unsupported schema node ${JSON.stringify(schema)}`);
}

function shouldBrand(name) {
  return name.endsWith("Id") || name.endsWith("Reference") || name.endsWith("Position");
}

function renderDefinition(name, schema) {
  const typeName = typeNameFromDefinition(name);
  const type = typeForSchema(schema);
  const branded = shouldBrand(typeName) ? ` & Brand<${literal(typeName)}>` : "";
  return `export type ${typeName} = ${type}${branded};`;
}

export function generateCommonV2Source(root = repositoryRoot) {
  const schemaPath = join(root, schemaRelativePath);
  if (!existsSync(schemaPath)) {
    throw new Error(`contract.generator-schema-missing: ${schemaRelativePath}`);
  }
  const schemaBytes = readFileSync(schemaPath);
  const schema = JSON.parse(schemaBytes.toString("utf8"));
  if (schema.$id !== schemaId) {
    throw new Error(`contract.generator-schema-id: expected ${schemaId}`);
  }
  const definitions = Object.entries(schema.$defs ?? {})
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([name, definition]) => renderDefinition(name, definition));
  const schemaHash = createHash("sha256").update(schemaBytes).digest("hex");
  return [
    generatedTypeHeader,
    `// Source schema: ${schemaRelativePath}`,
    `// Source schema SHA-256: ${schemaHash}`,
    "",
    "declare const officeV2Brand: unique symbol;",
    "type Brand<Name extends string> = { readonly [officeV2Brand]: Name };",
    "",
    ...definitions,
    "",
  ].join("\n");
}

export function expectedGeneratedFiles(root = repositoryRoot) {
  return new Map([[generatedRelativePath, generateCommonV2Source(root)]]);
}

export function checkGeneratedFiles(root = repositoryRoot) {
  const expected = expectedGeneratedFiles(root);
  const generatedRoot = join(root, "packages/office-v2-contracts/src/generated");
  const actualFiles = existsSync(generatedRoot)
    ? readdirSync(generatedRoot).filter((file) => file.endsWith(".ts")).sort()
    : [];
  const expectedFiles = [...expected.keys()].map((path) => path.slice(path.lastIndexOf("/") + 1)).sort();
  const unexpected = actualFiles.filter((file) => !expectedFiles.includes(file));
  if (unexpected.length > 0) {
    throw new Error(`contract.generated-drift: unexpected generated files ${unexpected.join(", ")}`);
  }
  for (const [path, content] of expected) {
    const absolutePath = join(root, path);
    if (!existsSync(absolutePath)) {
      throw new Error(`contract.generated-drift: missing ${path}`);
    }
    const actual = readFileSync(absolutePath, "utf8");
    if (actual !== content) {
      throw new Error(`contract.generated-drift: generated bytes differ for ${path}`);
    }
  }
  return "Office V2 generated contracts are deterministic and drift-free.";
}

export function writeGeneratedFiles(root = repositoryRoot) {
  for (const [path, content] of expectedGeneratedFiles(root)) {
    const absolutePath = join(root, path);
    mkdirSync(dirname(absolutePath), { recursive: true });
    writeFileSync(absolutePath, content);
  }
  return "Office V2 generated contracts written.";
}

function main() {
  const mode = process.argv[2];
  if (mode === "--write") {
    console.log(writeGeneratedFiles());
  } else if (mode === "--check") {
    console.log(checkGeneratedFiles());
  } else {
    throw new Error("Usage: node scripts/office-v2-contracts-generate.mjs --write|--check");
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  try {
    main();
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}
